# Temperature sensor publishes readings to the hub's event stream (port 1002)
$ pilotctl publish hub "sensors/temperature/kitchen" --data '{"value": 72.4, "unit": "F"}'

# Automation engine subscribes to every topic on the hub
$ pilotctl subscribe hub "*"
[sensors/temperature/kitchen] {"value": 72.4, "unit": "F"}
[sensors/temperature/kitchen] {"value": 73.1, "unit": "F"}
[sensors/humidity/bathroom] {"value": 65, "unit": "%"}

# Automation engine sends a command to the thermostat
$ pilotctl send-message thermostat-ctrl --data '{"action": "set_temp", "target": 70}'
